import React, { useEffect, useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, Plus, HeartPulse, BarChart3, LogOut, Zap, Flame, Trophy, Sparkles, RefreshCw, ArrowRight, Check, Moon, MessageSquare, Clock } from "lucide-react";

type Row = Record<string, unknown>;
const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2,.sx h3,.sx h4{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx .tnum{font-variant-numeric:tabular-nums}
.sx .disp{font-weight:800;letter-spacing:-0.03em;text-transform:uppercase;line-height:.95}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const CARD = "rounded-2xl border border-white/[0.07] bg-[#14160F]";
const NAV = [
  { to: "/", label: "Today", I: Home },
  { to: "/log", label: "Log", I: Plus },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];

const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const fmt = (s: string, o: Intl.DateTimeFormatOptions): string => (s ? new Date(s + "T00:00:00Z").toLocaleDateString("en-US", { ...o, timeZone: "UTC" }) : "");
const diffDays = (a: string, b: string): number => Math.round((new Date(a + "T00:00:00Z").getTime() - new Date(b + "T00:00:00Z").getTime()) / 86400000);
function rel(d: string, today: string): string {
  const n = diffDays(today, d);
  if (n <= 0) return "Today";
  if (n === 1) return "Yesterday";
  if (n < 7) return n + " days ago";
  return fmt(d, { month: "short", day: "numeric" });
}

type Ex = { n?: string; s?: number; r?: number; w?: number; km?: number; min?: number };
function parseEx(v: unknown): Ex[] {
  try {
    const j = JSON.parse(String(v ?? "[]"));
    return Array.isArray(j) ? (j as Ex[]) : [];
  } catch (e) {
    return [];
  }
}
function calcStreak(days: Set<string>, today: string): number {
  let cur = days.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (days.has(cur)) {
    n++;
    cur = addDays(cur, -1);
  }
  return n;
}

function Brand() {
  return (
    <div className="flex items-center gap-2">
      <span className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-[#0B0C09]"><Zap size={18} strokeWidth={2.5} aria-hidden /></span>
      <span className="text-xl font-extrabold uppercase tracking-tight">Stride</span>
    </div>
  );
}

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  const name = app?.user.name || "Athlete";
  const out = (
    <button type="button" aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-11 w-11 place-items-center rounded-xl text-[#B4B8A9] transition-colors hover:bg-white/[0.06] hover:text-[#F2F3EC]">
      <LogOut size={18} aria-hidden />
    </button>
  );
  return (
    <div className="sx min-h-[100dvh] bg-[#0B0C09] text-[#F2F3EC]">
      <style>{CSS}</style>
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-60 flex-col border-r border-white/[0.07] bg-[#0E100B] px-4 py-6 lg:flex">
        <div className="px-2"><Brand /></div>
        <nav aria-label="Main" className="mt-8 space-y-1">
          {NAV.map((n) => {
            const on = active === n.to;
            return (
              <button key={n.to} type="button" aria-current={on ? "page" : undefined} onClick={() => app?.navigate(n.to)} className={"flex h-11 w-full items-center gap-3 rounded-xl px-3 text-left text-[15px] font-semibold transition-colors " + (on ? "bg-white/[0.08] text-[#F2F3EC]" : "text-[#B4B8A9] hover:bg-white/[0.04] hover:text-[#F2F3EC]")}>
                <n.I size={18} aria-hidden className={on ? "text-primary" : ""} />
                {n.label}
              </button>
            );
          })}
        </nav>
        <div className="mt-auto flex items-center gap-3 border-t border-white/[0.07] pt-4">
          <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white/[0.08] text-sm font-bold">{name.slice(0, 1)}</span>
          <div className="min-w-0 flex-1">
            <div className="truncate text-sm font-semibold">{name}</div>
            <div className="text-[13px] text-[#9A9E8F]">Athlete</div>
          </div>
          {out}
        </div>
      </aside>
      <header className="sticky top-0 z-30 flex h-14 items-center justify-between border-b border-white/[0.07] bg-[#0B0C09] pl-4 pr-2 lg:hidden">
        <Brand />
        {out}
      </header>
      <main className="lg:pl-60">
        <div className="mx-auto max-w-6xl px-4 pb-28 pt-6 sm:px-6 lg:px-10 lg:pb-16 lg:pt-10">{children}</div>
      </main>
      <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-40 border-t border-white/[0.08] bg-[#0E100B] pb-[env(safe-area-inset-bottom)] lg:hidden">
        <div className="mx-auto grid max-w-md grid-cols-4">
          {NAV.map((n) => {
            const on = active === n.to;
            return (
              <button key={n.to} type="button" aria-current={on ? "page" : undefined} onClick={() => app?.navigate(n.to)} className="flex h-16 flex-col items-center justify-center gap-1 text-xs font-semibold">
                <span className={"grid h-8 w-14 place-items-center rounded-full transition-colors " + (on ? "bg-primary text-[#0B0C09]" : "text-[#B4B8A9]")}><n.I size={20} aria-hidden /></span>
                <span className={on ? "text-[#F2F3EC]" : "text-[#A3A797]"}>{n.label}</span>
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
}

function Sk({ className }: { className: string }) {
  return <div className={"animate-pulse rounded-lg bg-white/[0.06] " + className} />;
}

export default function AthleteHome({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [hour] = useState(() => new Date().getHours());
  const [metric, setMetric] = useState<"minutes" | "volume" | "distance">("minutes");
  const [tip, setTip] = useState("");
  const [tipBusy, setTipBusy] = useState(false);
  const [tipSource, setTipSource] = useState<"ai" | "logs" | "">("");

  const me = app?.me("athlete");
  const loading = app ? app.loading("workout") : false;
  const all = app ? app.rows("workout") : [];
  const plans = app ? app.rows("plan_day") : [];
  const checkins = app ? app.rows("checkin") : [];
  const feedback = app ? app.rows("feedback") : [];
  const digests = app ? app.rows("digest") : [];
  const athletes = app ? app.rows("athlete") : [];
  const coaches = app ? app.rows("coach") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const coach = coaches.find((c) => mine && String(c.id) === String(mine.coach_id));

  const workouts = useMemo(() => all.filter((w) => !me || String(w.athlete_id) === me), [all, me]);
  const days = useMemo(() => new Set(workouts.map((w) => ds(w.day))), [workouts]);
  const streak = calcStreak(days, today);
  const best = useMemo(() => {
    const sorted = Array.from(days).sort();
    let b = 0;
    let run = 0;
    let prev = "";
    for (const d of sorted) {
      run = prev && addDays(prev, 1) === d ? run + 1 : 1;
      if (run > b) b = run;
      prev = d;
    }
    return b;
  }, [days]);

  const week = useMemo(
    () =>
      Array.from({ length: 7 }, (_, i) => {
        const d = addDays(today, i - 6);
        const ws = workouts.filter((w) => ds(w.day) === d);
        return { d, minutes: ws.reduce((s, w) => s + num(w.duration_min), 0), volume: ws.reduce((s, w) => s + num(w.volume), 0), distance: ws.reduce((s, w) => s + num(w.distance_km), 0), n: ws.length };
      }),
    [workouts, today]
  );
  const sessions = week.reduce((s, d) => s + d.n, 0);
  const target = num(mine?.weekly_target) || 4;
  const recent = useMemo(() => workouts.filter((w) => ds(w.day) >= addDays(today, -6)).sort((a, b) => ds(b.day).localeCompare(ds(a.day))), [workouts, today]);
  const avgEffort = recent.length ? recent.reduce((s, w) => s + num(w.effort), 0) / recent.length : 0;
  const totMin = week.reduce((s, d) => s + d.minutes, 0);
  const totVol = week.reduce((s, d) => s + d.volume, 0);
  const totKm = week.reduce((s, d) => s + d.distance, 0);

  const todayPlan = plans.find((p) => ds(p.day) === today && (!me || String(p.athlete_id) === me));
  const nextPlan = [...plans].filter((p) => ds(p.day) > today).sort((a, b) => ds(a.day).localeCompare(ds(b.day)))[0];
  const doneToday = workouts.some((w) => ds(w.day) === today);
  const myChecks = checkins.filter((c) => !me || String(c.athlete_id) === me);
  const checkedIn = myChecks.some((c) => ds(c.day) === today);
  const lastCheckin = [...myChecks].sort((a, b) => ds(b.day).localeCompare(ds(a.day)))[0];

  const prs = useMemo(() => {
    const lifts = new Map<string, { w: number; r: number; day: string }>();
    let longest = { km: 0, day: "" };
    let pace = { p: 99, day: "" };
    for (const w of workouts) {
      for (const e of parseEx(w.exercises)) {
        const wt = num(e.w);
        if (e.n && wt > 0) {
          const cur = lifts.get(e.n);
          if (!cur || wt > cur.w || (wt === cur.w && ds(w.day) < cur.day)) lifts.set(e.n, { w: wt, r: num(e.r), day: ds(w.day) });
        }
      }
      if (String(w.kind) === "run") {
        const km = num(w.distance_km);
        if (km > longest.km) longest = { km, day: ds(w.day) };
        if (km >= 3) {
          const p = num(w.duration_min) / km;
          if (p < pace.p) pace = { p, day: ds(w.day) };
        }
      }
    }
    const fresh = addDays(today, -7);
    const out: { name: string; value: string; unit: string; day: string; isNew: boolean }[] = [];
    Array.from(lifts.entries())
      .sort((a, b) => b[1].w - a[1].w)
      .slice(0, 4)
      .forEach(([n, v]) => out.push({ name: n, value: String(v.w), unit: "kg" + (v.r ? " × " + v.r : ""), day: v.day, isNew: v.day > fresh }));
    if (longest.km) out.push({ name: "Longest run", value: String(longest.km), unit: "km", day: longest.day, isNew: longest.day > fresh });
    if (pace.p < 99) {
      const m = Math.floor(pace.p);
      const s = Math.round((pace.p - m) * 60);
      out.push({ name: "Best pace", value: m + ":" + String(s).padStart(2, "0"), unit: "/km", day: pace.day, isNew: pace.day > fresh });
    }
    return out;
  }, [workouts, today]);

  const fbList = useMemo(() => [...feedback].sort((a, b) => String(b.created_at ?? "").localeCompare(String(a.created_at ?? ""))).slice(0, 3), [feedback]);
  const lastDigest = [...digests].sort((a, b) => ds(b.week_start).localeCompare(ds(a.week_start)))[0];

  function fallbackTip(): string {
    if (!recent.length) return "Nothing logged in the last 7 days. A 20-minute easy session today restarts the habit without digging a hole.";
    const hard = recent.filter((w) => num(w.effort) >= 8).length;
    const sore = lastCheckin ? num(lastCheckin.soreness) : 0;
    if (sore >= 4) return "Soreness was " + sore + "/5 on your last check-in. Swap the next hard session for 30 minutes of mobility and get an extra hour of sleep.";
    if (hard >= 3) return hard + " sessions at effort 8 or higher this week. Keep the next one at a 5 so the work actually turns into fitness.";
    const top = recent[0];
    return "Good work on " + String(top.title) + ". Keep the next session around effort " + Math.max(5, Math.min(7, num(top.effort))) + " and aim to match last week's numbers, not beat them.";
  }

  async function getTip() {
    if (!app) return;
    setTipBusy(true);
    const lines = recent.map((w) => ds(w.day) + ": " + String(w.title) + " (" + String(w.kind) + "), effort " + num(w.effort) + "/10, " + num(w.duration_min) + " min" + (num(w.volume) ? ", " + num(w.volume) + " kg volume" : "") + (num(w.distance_km) ? ", " + num(w.distance_km) + " km" : "") + (w.notes ? ", note: " + String(w.notes) : ""));
    const ck = myChecks.filter((c) => ds(c.day) >= addDays(today, -6)).map((c) => ds(c.day) + ": sleep " + num(c.sleep_hours) + " h, mood " + num(c.mood) + "/5, soreness " + num(c.soreness) + "/5");
    try {
      const timeout = new Promise<string>((_, rej) => setTimeout(() => rej(new Error("timeout")), 15000));
      const a = await Promise.race([timeout, app.ai.ask(
        "Athlete logs from the last 7 days:\n" + (lines.join("\n") || "none") + "\nCheck-ins:\n" + (ck.join("\n") || "none") + "\nToday's plan: " + (todayPlan ? String(todayPlan.title) + " (" + String(todayPlan.details ?? "") + ")" : "none") + "\nGoal: " + String(mine?.goal ?? "get fitter") + "\nGive ONE specific coaching tip for the next session.",
        { system: "You are a sharp, warm strength and endurance coach. Reply with exactly one tip in at most two short sentences (under 45 words). Cite a concrete number or exercise from the logs. No preamble, no lists, no emoji, no markdown.", maxTokens: 120 }
      )]);
      const t = a.trim().replace(/^["']|["']$/g, "");
      if (!t) throw new Error("empty");
      setTip(t);
      setTipSource("ai");
    } catch (e) {
      setTip(fallbackTip());
      setTipSource("logs");
    }
    setTipBusy(false);
  }

  const ready = !loading && workouts.length > 0;
  useEffect(() => {
    if (ready && !tip && !tipBusy) void getTip();
    // eslint-disable-next-line
  }, [ready]);

  const series = week.map((d) => (metric === "minutes" ? d.minutes : metric === "volume" ? d.volume : d.distance));
  const maxV = Math.max(1, ...series);
  const unit = metric === "minutes" ? "min" : metric === "volume" ? "kg" : "km";
  const greet = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const first = (app?.user.name || "Athlete").split(" ")[0];
  const enter = (i: number) => ({ initial: reduce ? false : { opacity: 0, y: 8 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.35, delay: reduce ? 0 : i * 0.04, ease: EASE } });
  const pct = Math.min(1, sessions / target);

  const stats: { l: string; v: string; u: string }[] = [
    { l: "Sessions", v: String(sessions), u: "of " + target },
    { l: "Training time", v: totMin >= 60 ? (Math.floor(totMin / 60) + "h " + String(totMin % 60).padStart(2, "0")) : String(totMin), u: totMin >= 60 ? "" : "min" },
    { l: "Lifted", v: totVol.toLocaleString("en-US"), u: "kg" },
    { l: "Distance", v: String(Math.round(totKm * 10) / 10), u: "km" },
  ];

  return (
    <Shell app={app} active="/">
      <motion.header {...enter(0)} className="mb-6 lg:mb-8">
        <h1 className="disp text-[40px] sm:text-5xl lg:text-6xl">
          {greet}, <span className="text-primary">{first}</span>
        </h1>
        <p className="mt-3 text-[15px] text-[#B4B8A9]">
          {fmt(today, { weekday: "long", month: "long", day: "numeric" })}
          {coach ? " · Coached by " + String(coach.name) : ""}
        </p>
      </motion.header>

      <div className="grid gap-4 lg:grid-cols-12 lg:gap-5">
        <motion.section {...enter(1)} aria-labelledby="today-h" className={CARD + " relative isolate flex min-h-[340px] flex-col justify-end overflow-hidden lg:col-span-7"}>
          {todayPlan?.image ? <img alt="" src={String(todayPlan.image)} className="absolute inset-0 -z-10 h-full w-full object-cover opacity-70" /> : null}
          <div className="absolute inset-0 -z-10 bg-gradient-to-t from-[#0B0C09] via-[#0B0C09]/85 to-[#0B0C09]/20" />
          <div className="p-5 sm:p-7">
            <p className="text-sm font-semibold text-primary">{doneToday ? "Done today" : todayPlan ? "Today's session" : "No session planned"}</p>
            {todayPlan ? (
              <>
                <h2 id="today-h" className="disp mt-2 text-4xl sm:text-5xl">{String(todayPlan.title)}</h2>
                <p className="mt-3 max-w-lg text-[15px] leading-relaxed text-[#E1E3DA]">{String(todayPlan.details ?? "")}</p>
                <div className="mt-5 flex flex-wrap items-center gap-x-5 gap-y-3">
                  <button type="button" onClick={() => app?.navigate("/log")} className="flex h-12 items-center gap-2 rounded-xl bg-primary px-5 text-[15px] font-bold text-[#0B0C09] transition-transform active:scale-[0.98]">
                    {doneToday ? "Log another session" : "Log this session"} <ArrowRight size={18} strokeWidth={2.5} aria-hidden />
                  </button>
                  <span className="tnum flex items-center gap-2 text-sm text-[#D3D6CB]"><Clock size={16} aria-hidden />{num(todayPlan.duration_min)} min · <span className="capitalize">{String(todayPlan.kind)}</span></span>
                </div>
              </>
            ) : (
              <>
                <h2 id="today-h" className="disp mt-2 text-4xl sm:text-5xl">Open day</h2>
                <p className="mt-3 max-w-lg text-[15px] leading-relaxed text-[#D3D6CB]">
                  {coach ? String(coach.name).split(" ")[0] + " hasn't planned anything for today." : "Nothing planned for today."} Train freely or take the recovery.
                  {nextPlan ? " Next up: " + String(nextPlan.title) + " on " + fmt(ds(nextPlan.day), { weekday: "long" }) + "." : ""}
                </p>
                <button type="button" onClick={() => app?.navigate("/log")} className="mt-5 flex h-12 w-fit items-center gap-2 rounded-xl bg-primary px-5 text-[15px] font-bold text-[#0B0C09] transition-transform active:scale-[0.98]">
                  Log a session <ArrowRight size={18} strokeWidth={2.5} aria-hidden />
                </button>
              </>
            )}
          </div>
        </motion.section>

        <motion.section {...enter(2)} aria-labelledby="streak-h" className={CARD + " flex flex-col p-5 sm:p-6 lg:col-span-5"}>
          <div className="flex items-start justify-between gap-4">
            <div>
              <h2 id="streak-h" className="flex items-center gap-2 text-sm font-semibold text-[#B4B8A9]"><Flame size={16} className="text-primary" aria-hidden /> Day streak</h2>
              {loading ? <Sk className="mt-2 h-16 w-24" /> : <div className="disp tnum mt-1 text-7xl text-[#F2F3EC]">{streak}</div>}
            </div>
            <div className="text-right text-sm text-[#B4B8A9]">
              <div>Best</div>
              <div className="tnum text-lg font-bold text-[#F2F3EC]">{Math.max(best, streak)} days</div>
            </div>
          </div>
          <ol className="mt-8 grid grid-cols-7 gap-2" aria-label="Last 7 days">
            {week.map((d) => {
              const isToday = d.d === today;
              return (
                <li key={d.d} className="flex flex-col items-center gap-1.5">
                  <span aria-hidden className={"grid h-12 w-full place-items-center rounded-xl " + (d.n ? "bg-primary text-[#0B0C09]" : isToday ? "border border-dashed border-primary/70" : "bg-white/[0.06]")}>
                    {d.n ? <Check size={16} strokeWidth={3} /> : null}
                  </span>
                  <span className={"text-xs " + (isToday ? "font-bold text-primary" : "text-[#9A9E8F]")}>{isToday ? "Today" : fmt(d.d, { weekday: "narrow" })}</span>
                  <span className="sr-only">{fmt(d.d, { weekday: "long" }) + (d.n ? ": trained" : ": rest")}</span>
                </li>
              );
            })}
          </ol>
          <div className="mt-auto pt-6">
            <div className="flex items-baseline justify-between text-sm">
              <span className="text-[#B4B8A9]">Weekly target</span>
              <span className="tnum font-semibold">{sessions} of {target} sessions{sessions >= target ? <span className="ml-2 text-primary">Target hit</span> : null}</span>
            </div>
            <div className="mt-2 h-2 overflow-hidden rounded-full bg-white/[0.07]" role="progressbar" aria-valuemin={0} aria-valuemax={target} aria-valuenow={sessions} aria-label="Sessions in the last 7 days">
              <motion.div className="h-full rounded-full bg-primary" initial={reduce ? false : { width: 0 }} animate={{ width: pct * 100 + "%" }} transition={{ duration: 0.6, ease: EASE }} />
            </div>
          </div>
        </motion.section>

        <motion.section {...enter(3)} aria-label="Last 7 days totals" className={CARD + " grid grid-cols-2 lg:col-span-12 lg:grid-cols-4"}>
          {stats.map((s, i) => (
            <div key={s.l} className={"p-5 " + (i % 2 === 1 ? "border-l border-white/[0.07] " : "") + (i >= 2 ? "border-t border-white/[0.07] lg:border-t-0 " : "") + (i === 2 ? "lg:border-l" : "")}>
              <div className="text-sm text-[#B4B8A9]">{s.l}</div>
              <div className="mt-1 flex items-baseline gap-1.5">
                {loading ? <Sk className="h-9 w-16" /> : <span className="tnum text-3xl font-extrabold tracking-tight sm:text-4xl">{s.v}</span>}
                <span className="text-sm text-[#9A9E8F]">{s.u}</span>
              </div>
            </div>
          ))}
          <p className="col-span-2 border-t border-white/[0.07] px-5 py-3 text-[13px] text-[#9A9E8F] lg:col-span-4">Rolling totals for the last 7 days · average effort <span className="tnum font-semibold text-[#D3D6CB]">{avgEffort.toFixed(1)}/10</span></p>
        </motion.section>

        <motion.section {...enter(4)} aria-labelledby="ai-h" className={CARD + " flex flex-col p-5 sm:p-6 lg:col-span-5"}>
          <div className="flex items-center justify-between gap-3">
            <h2 id="ai-h" className="flex items-center gap-2 text-lg font-bold"><Sparkles size={18} className="text-primary" aria-hidden /> Coach's tip</h2>
