import React, { useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, useReducedMotion } from "motion/react";
import { ArrowRight, Zap, Check } from "lucide-react";

const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx input::placeholder{color:#8F9384}
.sx input:-webkit-autofill{-webkit-box-shadow:0 0 0 40px #181A13 inset;-webkit-text-fill-color:#F2F3EC}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const IN = "h-12 w-full rounded-xl border border-white/[0.12] bg-[#181A13] px-4 text-base text-[#F2F3EC] outline-none transition-colors focus:border-primary";
const LBL = "mb-1.5 block text-sm font-semibold text-[#D3D6CB]";
const WEEK = ["M", "T", "W", "T", "F", "S", "S"];

function GoogleMark() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7a14.5 14.5 0 0 1 0-9.4l-7.9-6.1a24 24 0 0 0 0 21.6l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.8 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
