}

export default function StrideLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const signup = auth?.mode === "signup";
  const providers = auth?.providers ?? [];

  async function go(e: React.FormEvent) {
    e.preventDefault();
    if (!auth) return;
    setErr("");
    if (!email.trim() || !password) {
      setErr("Enter your email and password to continue.");
      return;
    }
    setBusy(true);
    try {
      if (signup) await auth.signUp({ email, password, name });
      else await auth.signIn(email, password);
    } catch (x) {
      setErr(x instanceof Error ? x.message : "That didn't work. Check your email and password and try again.");
    }
    setBusy(false);
  }

  async function provider(p: string) {
    if (!auth) return;
    setErr("");
    try {
      await auth.startProvider(p);
    } catch (x) {
      setErr(x instanceof Error ? x.message : "Couldn't start that sign-in. Try again.");
    }
  }

  const rise = (d: number) => ({ initial: reduce ? false : { opacity: 0, y: 12 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.5, delay: reduce ? 0 : d, ease: EASE } });

  return (
    <div className="sx min-h-[100dvh] w-full bg-[#0B0C09] text-[#F2F3EC]">
      <style>{CSS}</style>
      <div className="mx-auto grid min-h-[100dvh] w-full max-w-6xl grid-rows-[auto_1fr] px-5 pb-10 pt-6 sm:px-8 lg:px-12">
        <div className="flex items-center gap-2">
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-[#0B0C09]"><Zap size={18} strokeWidth={2.5} aria-hidden /></span>
          <span className="text-xl font-extrabold uppercase tracking-tight">Stride</span>
        </div>

        <div className="grid items-center gap-10 py-8 lg:grid-cols-[1.15fr_1fr] lg:gap-16 lg:py-0">
          <div>
            <motion.h1 {...rise(0.05)} aria-label="Move." className="select-none font-extrabold uppercase leading-[0.85] tracking-[-0.04em] text-primary" style={{ fontSize: "clamp(5.5rem, 26vw, 12.5rem)" }}>
              Move.
            </motion.h1>
            <motion.p {...rise(0.15)} className="mt-5 max-w-md text-lg leading-relaxed text-[#D3D6CB] lg:text-xl">
              {signup ? "Create your athlete account. Your coach's plan, your sessions and your streak, all in one place." : "Your coach's plan, your logged sessions and your streak, all in one place."}
            </motion.p>
            <motion.div {...rise(0.25)} className="mt-8 hidden max-w-sm sm:block" aria-hidden>
              <div className="flex gap-2">
                {WEEK.map((d, i) => (
                  <div key={i} className="flex flex-1 flex-col items-center gap-1.5">
                    <span className={"grid h-10 w-full place-items-center rounded-xl " + (i < 5 ? "bg-primary text-[#0B0C09]" : i === 5 ? "border border-dashed border-primary/70" : "bg-white/[0.06]")}>{i < 5 ? <Check size={16} strokeWidth={3} /> : null}</span>
                    <span className={"text-xs " + (i === 5 ? "font-bold text-primary" : "text-[#9A9E8F]")}>{d}</span>
                  </div>
                ))}
              </div>
              <p className="mt-3 text-sm text-[#9A9E8F]">5 days in a row. Today keeps it going.</p>
            </motion.div>
          </div>

          <motion.div {...rise(0.2)} className="w-full lg:justify-self-end">
            <form onSubmit={(e) => void go(e)} noValidate className="w-full rounded-2xl border border-white/[0.08] bg-[#14160F] p-5 sm:p-7 lg:max-w-[420px]">
              <h2 className="text-2xl font-extrabold tracking-tight">{signup ? "Create your account" : "Welcome back"}</h2>
              <p className="mt-1 text-[15px] text-[#B4B8A9]">{signup ? "Takes less than a minute." : "Pick up where you left off."}</p>
              <div className="mt-6 space-y-4">
                {signup ? (
                  <div>
                    <label htmlFor="stride-name" className={LBL}>Name</label>
                    <input id="stride-name" autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} className={IN} placeholder="Your full name" />
                  </div>
                ) : null}
                <div>
                  <label htmlFor="stride-email" className={LBL}>Email</label>
                  <input id="stride-email" type="email" autoComplete="email" inputMode="email" value={email} onChange={(e) => setEmail(e.target.value)} className={IN} placeholder="you@example.com" />
                </div>
                <div>
                  <label htmlFor="stride-password" className={LBL}>Password</label>
                  <input id="stride-password" type="password" autoComplete={signup ? "new-password" : "current-password"} value={password} onChange={(e) => setPassword(e.target.value)} className={IN} />
                </div>
              </div>
              {err ? <p role="alert" className="mt-4 rounded-xl border border-[#FF6B6B]/30 bg-[#FF6B6B]/10 px-4 py-3 text-sm text-[#FFB3B3]">{err}</p> : null}
              <button type="submit" disabled={busy} className="mt-5 flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary text-base font-bold text-[#0B0C09] transition-transform active:scale-[0.99] disabled:opacity-60">
                {busy ? (signup ? "Creating account…" : "Signing in…") : signup ? "Create account" : "Sign in"} {busy ? null : <ArrowRight size={18} strokeWidth={2.5} aria-hidden />}
              </button>

              {providers.length > 0 ? (
                <>
                  <div className="my-5 flex items-center gap-3 text-sm text-[#9A9E8F]">
                    <span className="h-px flex-1 bg-white/[0.1]" />or<span className="h-px flex-1 bg-white/[0.1]" />
                  </div>
                  <div className="space-y-2">
                    {providers.map((p) => (
                      <button key={p.name} type="button" onClick={() => void provider(p.name)} className="flex h-12 w-full items-center justify-center gap-3 rounded-xl bg-white text-[15px] font-semibold text-[#1F1F1F] transition-colors hover:bg-[#F1F1EE]">
                        {p.name === "google" ? <GoogleMark /> : null}
                        Continue with {p.label}
                      </button>
                    ))}
                  </div>
                </>
              ) : null}

              {auth?.canSignUp ? (
                <p className="mt-5 text-center text-[15px] text-[#B4B8A9]">
                  {signup ? "Already training with Stride? " : "New to Stride? "}
                  <button type="button" onClick={() => auth.setMode(signup ? "login" : "signup")} className="inline-flex h-11 items-center font-semibold text-primary underline-offset-4 hover:underline">
                    {signup ? "Sign in" : "Create an account"}
                  </button>
                </p>
              ) : null}
            </form>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, Plus, HeartPulse, BarChart3, LogOut, Zap, Check, ChevronDown, ChevronUp, Moon } from "lucide-react";

type Row = Record<string, unknown>;
const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2,.sx h3,.sx h4{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx .tnum{font-variant-numeric:tabular-nums}
.sx .disp{font-weight:800;letter-spacing:-0.03em;text-transform:uppercase;line-height:.95}
.sx textarea::placeholder,.sx input::placeholder{color:#8F9384}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const CARD = "rounded-2xl border border-white/[0.07] bg-[#14160F]";
const NAV = [
  { to: "/", label: "Today", I: Home },
  { to: "/log", label: "Log", I: Plus },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];
const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const fmt = (s: string, o: Intl.DateTimeFormatOptions): string => (s ? new Date(s + "T00:00:00Z").toLocaleDateString("en-US", { ...o, timeZone: "UTC" }) : "");
const MOOD_L = ["Rough", "Low", "Okay", "Good", "Great"];
const SORE_L = ["Fresh", "Light", "Moderate", "Sore", "Very sore"];

function Brand() {
  return (
    <div className="flex items-center gap-2">
      <span className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-[#0B0C09]"><Zap size={18} strokeWidth={2.5} aria-hidden /></span>
      <span className="text-xl font-extrabold uppercase tracking-tight">Stride</span>
    </div>
  );
}

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
