        {out}
      </header>
      <main className="lg:pl-60">
        <div className="mx-auto max-w-5xl px-4 pb-28 pt-6 sm:px-6 lg:px-10 lg:pb-16 lg:pt-10">{children}</div>
      </main>
      <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-40 border-t border-white/[0.08] bg-[#0E100B] pb-[env(safe-area-inset-bottom)] lg:hidden">
