          {NAV.map((n) => {
            const on = active === n.to;
            return (
              <button key={n.to} type="button" aria-current={on ? "page" : undefined} onClick={() => app?.navigate(n.to)} className="flex h-16 flex-col items-center justify-center gap-1 text-xs font-semibold">
                <span className={"grid h-8 w-14 place-items-center rounded-full transition-colors " + (on ? "bg-primary text-[#0B0C09]" : "text-[#B4B8A9]")}><n.I size={20} aria-hidden /></span>
