function Scale({ label, value, onChange, words, warnFrom }: { label: string; value: number; onChange: (n: number) => void; words: string[]; warnFrom?: number }) {
  return (
    <fieldset>
      <legend className="flex w-full items-baseline justify-between text-[15px] font-semibold">
        <span>{label}</span>
        <span className={"text-sm font-semibold " + (warnFrom && value >= warnFrom ? "text-[#FF9B5E]" : "text-primary")}>{words[value - 1]}</span>
      </legend>
      <div className="mt-3 grid grid-cols-5 gap-2">
        {[1, 2, 3, 4, 5].map((n) => {
          const on = n === value;
          const warn = warnFrom !== undefined && on && n >= warnFrom;
          return (
            <button key={n} type="button" aria-pressed={on} aria-label={label + " " + n + " of 5, " + words[n - 1]} onClick={() => onChange(n)} className={"flex h-14 flex-col items-center justify-center rounded-xl border text-base font-bold transition-colors " + (on ? (warn ? "border-[#FF9B5E] bg-[#FF9B5E] text-[#0B0C09]" : "border-primary bg-primary text-[#0B0C09]") : "border-white/[0.08] bg-white/[0.04] text-[#D3D6CB] hover:bg-white/[0.08]")}>
              <span className="tnum">{n}</span>
            </button>
          );
        })}
      </div>
      <div className="mt-1.5 flex justify-between text-xs text-[#9A9E8F]"><span>{words[0]}</span><span>{words[4]}</span></div>
    </fieldset>
  );
}

export default function CheckIn({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const me = app?.me("athlete");
  const athletes = app ? app.rows("athlete") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const loading = app ? app.loading("checkin") : false;
  const rows = (app ? app.rows("checkin") : []).filter((c) => !me || String(c.athlete_id) === me);
  const existing = rows.find((c) => ds(c.day) === today);
  const [sleep, setSleep] = useState(7.5);
  const [mood, setMood] = useState(4);
  const [sore, setSore] = useState(2);
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [saved, setSaved] = useState(false);
  const [justNow, setJustNow] = useState<Row | null>(null);

  const shown = existing || justNow;
  const hist = Array.from({ length: 7 }, (_, i) => {
    const d = addDays(today, i - 6);
    const r = rows.find((c) => ds(c.day) === d) || (d === today && justNow ? justNow : undefined);
    return { d, r };
  });
  const logged = hist.filter((h) => h.r);
  const avgSleep = logged.length ? logged.reduce((s, h) => s + num(h.r?.sleep_hours), 0) / logged.length : 0;

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (!app) return;
    setBusy(true);
    setErr("");
    try {
      const vals = { athlete_id: me, coach_id: mine?.coach_id ?? null, athlete_name: app.user.name, day: today, sleep_hours: sleep, mood, soreness: sore, note: note.trim() };
      await app.create("checkin", vals);
      setJustNow(vals);
      setSaved(true);
    } catch (x) {
      setErr(x instanceof Error ? x.message : "Couldn't save your check-in. Check your connection and try again.");
    }
    setBusy(false);
  }

  const step = (d: number) => setSleep((s) => Math.max(0, Math.min(14, Math.round((s + d) * 10) / 10)));
  return (
    <Shell app={app} active="/checkin">
      <header className="mb-6 lg:mb-8">
        <h1 className="disp text-[40px] sm:text-5xl lg:text-6xl">Daily check-in</h1>
        <p className="mt-3 max-w-xl text-[15px] text-[#B4B8A9]">How you slept and how your body feels. Takes 20 seconds, and your coach uses it to adjust the plan.</p>
      </header>

      <div className="grid gap-4 lg:grid-cols-5 lg:gap-5">
        <div className="lg:col-span-3">
          {loading && !shown ? (
            <div className={CARD + " h-[480px] animate-pulse"} />
          ) : (
            <AnimatePresence mode="wait" initial={false}>
              {shown ? (
                <motion.section key="done" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35, ease: EASE }} className={CARD + " p-6 sm:p-8"} aria-live="polite">
                  <div className="flex items-center gap-4">
                    <span className="grid h-12 w-12 shrink-0 place-items-center rounded-full bg-primary text-[#0B0C09]"><Check size={24} strokeWidth={3} aria-hidden /></span>
                    <div>
                      <h2 className="text-2xl font-extrabold tracking-tight">{saved ? "Check-in saved" : "You've checked in today"}</h2>
                      <p className="text-[15px] text-[#B4B8A9]">One per day. Come back tomorrow morning.</p>
                    </div>
                  </div>
                  <dl className="mt-6 grid grid-cols-3 gap-2">
                    <div className="rounded-xl bg-white/[0.05] p-4"><dt className="text-[13px] text-[#9A9E8F]">Sleep</dt><dd className="tnum mt-1 text-3xl font-extrabold tracking-tight">{num(shown.sleep_hours)}<span className="ml-0.5 text-base font-semibold text-[#B4B8A9]">h</span></dd></div>
                    <div className="rounded-xl bg-white/[0.05] p-4"><dt className="text-[13px] text-[#9A9E8F]">Mood</dt><dd className="mt-1 text-xl font-extrabold">{MOOD_L[Math.max(0, Math.min(4, num(shown.mood) - 1))]}</dd></div>
                    <div className="rounded-xl bg-white/[0.05] p-4"><dt className="text-[13px] text-[#9A9E8F]">Soreness</dt><dd className="tnum mt-1 text-3xl font-extrabold tracking-tight">{num(shown.soreness)}<span className="text-base font-semibold text-[#B4B8A9]">/5</span></dd></div>
                  </dl>
                  {shown.note ? <p className="mt-4 rounded-xl bg-white/[0.05] p-4 text-[15px] text-[#E1E3DA]">“{String(shown.note)}”</p> : null}
                  <button type="button" onClick={() => app?.navigate("/log")} className="mt-6 h-12 w-full rounded-xl border border-white/[0.14] text-[15px] font-semibold transition-colors hover:bg-white/[0.05] sm:w-auto sm:px-6">Log today's session</button>
                </motion.section>
              ) : (
                <motion.div key="form" exit={{ opacity: 0 }}>
                <form onSubmit={(e) => void save(e)} className={CARD + " space-y-8 p-5 sm:p-7"}>
                  <fieldset>
                    <legend className="text-[15px] font-semibold">Sleep last night</legend>
                    <div className="mt-3 flex items-center justify-between gap-4 rounded-xl bg-white/[0.04] p-2">
                      <button type="button" aria-label="Less sleep" onClick={() => step(-0.5)} className="grid h-12 w-12 place-items-center rounded-lg bg-white/[0.07] transition-colors hover:bg-white/[0.12]"><ChevronDown size={22} aria-hidden /></button>
                      <div className="text-center" aria-live="polite">
                        <span className="tnum text-6xl font-extrabold tracking-tight">{sleep.toFixed(1)}</span>
                        <span className="ml-1 text-lg font-semibold text-[#B4B8A9]">hours</span>
                      </div>
                      <button type="button" aria-label="More sleep" onClick={() => step(0.5)} className="grid h-12 w-12 place-items-center rounded-lg bg-white/[0.07] transition-colors hover:bg-white/[0.12]"><ChevronUp size={22} aria-hidden /></button>
                    </div>
                    {sleep < 6 ? <p className="mt-2 text-sm text-[#FF9B5E]">Under 6 hours. Your coach will see this flagged.</p> : null}
                  </fieldset>
                  <Scale label="Mood" value={mood} onChange={setMood} words={MOOD_L} />
                  <Scale label="Soreness" value={sore} onChange={setSore} words={SORE_L} warnFrom={4} />
                  <div>
                    <label htmlFor="ck-note" className="text-[15px] font-semibold">Note for your coach <span className="font-normal text-[#9A9E8F]">(optional)</span></label>
                    <textarea id="ck-note" rows={3} value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g. Left calf tight after yesterday's run" className="mt-2 w-full rounded-xl border border-white/[0.1] bg-white/[0.04] p-4 text-[15px] text-[#F2F3EC] outline-none transition-colors focus:border-primary" />
                  </div>
                  {err ? <p role="alert" className="rounded-xl border border-[#FF6B6B]/30 bg-[#FF6B6B]/10 px-4 py-3 text-sm text-[#FFB3B3]">{err}</p> : null}
                  <button type="submit" disabled={busy || !app} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary text-base font-bold text-[#0B0C09] transition-transform active:scale-[0.99] disabled:opacity-60">
                    {busy ? "Saving…" : "Save check-in"}
                  </button>
                </form>
                </motion.div>
              )}
            </AnimatePresence>
          )}
        </div>

        <section aria-labelledby="trend-h" className={CARD + " p-5 sm:p-6 lg:col-span-2 lg:self-start"}>
          <div className="flex items-baseline justify-between">
            <h2 id="trend-h" className="text-lg font-bold">Last 7 days</h2>
            <span className="text-[13px] text-[#9A9E8F]">{logged.length} of 7 logged</span>
          </div>
          {logged.length === 0 ? (
            <div className="mt-6 flex flex-col items-center rounded-xl bg-white/[0.03] px-4 py-10 text-center">
              <Moon size={22} className="text-primary" aria-hidden />
              <p className="mt-3 text-[15px] font-semibold">No check-ins this week</p>
              <p className="mt-1 text-sm text-[#B4B8A9]">Your sleep and soreness trend builds from the first one.</p>
            </div>
          ) : (
            <>
              <div className="mt-5 flex items-baseline justify-between text-sm">
                <span className="font-semibold">Sleep</span>
                <span className="text-[#B4B8A9]">avg <span className="tnum font-semibold text-[#F2F3EC]">{avgSleep.toFixed(1)} h</span></span>
              </div>
              <div className="mt-3 flex h-28 items-end gap-2">
                {hist.map((h, i) => {
                  const v = num(h.r?.sleep_hours);
                  return (
                    <div key={h.d} className="flex h-full flex-1 flex-col items-center justify-end gap-1">
                      <span className="tnum text-xs text-[#D3D6CB]">{h.r ? v : ""}</span>
                      <motion.div initial={reduce ? false : { height: 0 }} animate={{ height: h.r ? Math.max(8, (v / 10) * 100) + "%" : "6%" }} transition={{ duration: 0.45, delay: reduce ? 0 : i * 0.03, ease: EASE }} className={"w-full rounded-md " + (h.r ? (v < 6 ? "bg-[#FF9B5E]" : "bg-primary") : "bg-white/[0.06]")} />
                    </div>
                  );
                })}
              </div>
              <div className="mt-6 text-sm font-semibold">Mood and soreness</div>
              <table className="mt-2 w-full table-fixed text-center text-sm">
                <thead>
                  <tr className="text-xs text-[#9A9E8F]">
                    <th className="w-[72px] text-left font-normal"><span className="sr-only">Metric</span></th>
                    {hist.map((h) => <th key={h.d} className={"pb-1 " + (h.d === today ? "font-bold text-primary" : "font-normal")}><span aria-hidden>{fmt(h.d, { weekday: "narrow" })}</span><span className="sr-only">{h.d === today ? "Today" : fmt(h.d, { weekday: "long" })}</span></th>)}
                  </tr>
                </thead>
                <tbody className="tnum">
                  <tr>
                    <th className="py-1.5 text-left text-[13px] font-normal text-[#B4B8A9]">Mood</th>
                    {hist.map((h) => <td key={h.d} className={"py-1.5 font-semibold " + (h.r ? "text-[#F2F3EC]" : "text-[#8F9384]")}>{h.r ? num(h.r.mood) : "–"}</td>)}
                  </tr>
                  <tr>
                    <th className="py-1.5 text-left text-[13px] font-normal text-[#B4B8A9]">Soreness</th>
                    {hist.map((h) => {
                      const s = num(h.r?.soreness);
                      return <td key={h.d} className={"py-1.5 font-semibold " + (!h.r ? "text-[#8F9384]" : s >= 4 ? "text-[#FF9B5E]" : "text-[#F2F3EC]")}>{h.r ? s : "–"}</td>;
                    })}
                  </tr>
                </tbody>
              </table>
              <p className="mt-4 text-[13px] text-[#9A9E8F]">Both on a 1 to 5 scale. Orange means sleep under 6 hours or soreness of 4 or more.</p>
            </>
          )}
        </section>
      </div>
    </Shell>
  );
}

import React, { useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, Plus, HeartPulse, BarChart3, LogOut, Zap, X, Check, Flame, ArrowRight } from "lucide-react";

const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2,.sx h3,.sx h4{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx .tnum{font-variant-numeric:tabular-nums}
.sx .disp{font-weight:800;letter-spacing:-0.03em;text-transform:uppercase;line-height:.95}
