.sx input[type=number]::-webkit-inner-spin-button{opacity:.4}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const CARD = "rounded-2xl border border-white/[0.07] bg-[#14160F]";
const INPUT = "h-12 w-full rounded-xl border border-white/[0.1] bg-white/[0.04] px-4 text-[15px] text-[#F2F3EC] outline-none transition-colors [color-scheme:dark] focus:border-primary";
const LBL = "mb-1.5 block text-sm font-semibold text-[#D3D6CB]";
const NAV = [
  { to: "/", label: "Today", I: Home },
  { to: "/log", label: "Log", I: Plus },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];
const KINDS = ["strength", "run", "conditioning", "mobility", "ride", "other"] as const;
type Kind = (typeof KINDS)[number];
const LIFTS = ["Back squat", "Bench press", "Deadlift", "Overhead press", "Pull-up", "Barbell row"];
const CARDIO = ["Easy run", "Intervals", "Long run", "Ride"];
const EFFORT_WORD = (n: number): string => (n <= 3 ? "Easy" : n <= 6 ? "Moderate" : n <= 8 ? "Hard" : n === 9 ? "Very hard" : "All out");

const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

