          <motion.div initial={reduce ? false : { scale: 0.6, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={t(0)} className="grid h-28 w-28 place-items-center rounded-full bg-primary text-[#0B0C09]">
            <svg width="52" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <motion.path d="M4 12.5l5 5L20 6.5" initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.4, delay: reduce ? 0 : 0.2, ease: EASE }} />
            </svg>
          </motion.div>
        </div>
        <motion.h2 id="done-h" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={t(0.25)} className="disp mt-7 text-5xl">Session <span className="text-primary">done</span></motion.h2>
        <motion.p initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} transition={t(0.3)} className="mt-3 text-[15px] text-[#B4B8A9]">{title} is logged. Your coach has been notified.</motion.p>
        <motion.dl initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={t(0.35)} className="mt-6 grid w-full grid-cols-3 gap-2">
          <div className="rounded-xl bg-white/[0.06] p-3"><dt className="text-[13px] text-[#9A9E8F]">Streak</dt><dd className="tnum mt-1 flex items-center justify-center gap-1 text-2xl font-extrabold text-primary"><Flame size={18} aria-hidden />{streak}d</dd></div>
          <div className="rounded-xl bg-white/[0.06] p-3"><dt className="text-[13px] text-[#9A9E8F]">Minutes</dt><dd className="tnum mt-1 text-2xl font-extrabold">{minutes}</dd></div>
          <div className="rounded-xl bg-white/[0.06] p-3"><dt className="text-[13px] text-[#9A9E8F]">Lifted</dt><dd className="tnum mt-1 text-2xl font-extrabold">{volume ? volume.toLocaleString("en-US") : "–"}{volume ? <span className="text-sm font-semibold text-[#B4B8A9]"> kg</span> : null}</dd></div>
        </motion.dl>
        <motion.div initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} transition={t(0.45)} className="mt-6 grid w-full grid-cols-2 gap-3">
          <button type="button" onClick={onDone} className="h-12 rounded-xl border border-white/[0.16] text-[15px] font-semibold transition-colors hover:bg-white/[0.05]">Log another</button>
          <button type="button" onClick={onHome} className="flex h-12 items-center justify-center gap-2 rounded-xl bg-primary text-[15px] font-bold text-[#0B0C09]">Back to today <ArrowRight size={16} strokeWidth={2.5} aria-hidden /></button>
        </motion.div>
      </div>
    </motion.div>
  );
}

export default function LogWorkout({ app }: { app?: AppHandle }) {
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const me = app?.me("athlete");
  const athletes = app ? app.rows("athlete") : [];
  const mine = athletes.find((a) => String(a.id) === me) || athletes[0];
  const plans = app ? app.rows("plan_day") : [];
  const workouts = app ? app.rows("workout") : [];
  const plan = plans.find((p) => ds(p.day) === today && (!me || String(p.athlete_id) === me));

  const [title, setTitle] = useState("");
  const [kind, setKind] = useState<Kind>("strength");
  const [day, setDay] = useState(today);
  const [minutes, setMinutes] = useState("45");
  const [effort, setEffort] = useState(6);
  const [notes, setNotes] = useState("");
  const [exs, setExs] = useState<Ex[]>([]);
  const [nid, setNid] = useState(1);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [titleErr, setTitleErr] = useState(false);
  const [done, setDone] = useState<{ streak: number; volume: number; minutes: number; title: string } | null>(null);
  const [prefilled, setPrefilled] = useState(false);

  if (plan && !prefilled && !title) {
    setPrefilled(true);
    setTitle(String(plan.title));
    const k = String(plan.kind) as Kind;
    if ((KINDS as readonly string[]).includes(k)) setKind(k);
    if (num(plan.duration_min)) setMinutes(String(num(plan.duration_min)));
  }

  const cardio = kind === "run" || kind === "ride";
  function addEx(name: string) {
    setExs((x) => [...x, { id: nid, name, sets: "3", reps: "8", weight: "", km: "", min: "" }]);
    setNid((n) => n + 1);
  }
  function patchEx(id: number, p: Partial<Ex>) {
    setExs((x) => x.map((e) => (e.id === id ? { ...e, ...p } : e)));
  }
  const volume = exs.reduce((s, e) => s + num(e.sets) * num(e.reps) * num(e.weight), 0);
  const distance = exs.reduce((s, e) => s + num(e.km), 0);

  async function save(ev: React.FormEvent) {
    ev.preventDefault();
    if (!app) return;
    setErr("");
    if (!title.trim()) {
      setTitleErr(true);
      setErr("Give the session a name so you and your coach can find it later.");
      return;
    }
    if (day > today) {
      setErr("You can't log a workout for a future date. Pick today or an earlier day.");
      return;
    }
    setBusy(true);
    try {
      const exercises = exs.filter((e) => e.name.trim()).map((e) => (e.km || e.min ? { n: e.name, km: num(e.km), min: num(e.min) } : { n: e.name, s: num(e.sets), r: num(e.reps), w: num(e.weight) }));
      await app.create("workout", {
        athlete_id: me,
        coach_id: mine?.coach_id ?? null,
        athlete_name: app.user.name,
        day,
        title: title.trim(),
        kind,
        effort,
        duration_min: num(minutes),
        volume,
        distance_km: distance,
        exercises: JSON.stringify(exercises),
        notes: notes.trim(),
      });
      const set = new Set(workouts.filter((w) => !me || String(w.athlete_id) === me).map((w) => ds(w.day)));
      set.add(day);
      let cur = set.has(today) ? today : addDays(today, -1);
      let n = 0;
      while (set.has(cur)) {
        n++;
        cur = addDays(cur, -1);
      }
      setDone({ streak: n, volume, minutes: num(minutes), title: title.trim() });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save that workout. Check your connection and try again.");
    }
    setBusy(false);
  }

  function reset() {
    setDone(null);
    setTitle("");
    setExs([]);
    setNotes("");
    setEffort(6);
    setDay(today);
    setPrefilled(true);
  }

  const effortTone = (n: number) => (n >= 9 ? "bg-[#FF9B5E] text-[#0B0C09] border-[#FF9B5E]" : "bg-primary text-[#0B0C09] border-primary");

  return (
    <Shell app={app} active="/log">
      <header className="mb-6 lg:mb-8">
        <h1 className="disp text-[40px] sm:text-5xl lg:text-6xl">Log a workout</h1>
        <p className="mt-3 text-[15px] text-[#B4B8A9]">{plan ? "Filled in from today's plan: " + String(plan.title) + ". Change anything that went differently." : "No plan for today, so this is a free session. Log what you did."}</p>
      </header>

      <form onSubmit={(e) => void save(e)} className="grid gap-4 lg:grid-cols-5 lg:gap-5" noValidate>
        <div className="space-y-4 lg:col-span-3 lg:space-y-5">
          <section aria-labelledby="basics-h" className={CARD + " space-y-5 p-5 sm:p-6"}>
            <h2 id="basics-h" className="sr-only">Session details</h2>
            <div>
              <label htmlFor="lw-title" className={LBL}>Session name</label>
              <input id="lw-title" aria-invalid={titleErr} className={INPUT + (titleErr ? " border-[#FF8080]" : "")} value={title} onChange={(e) => { setTitle(e.target.value); setTitleErr(false); }} placeholder="e.g. Lower body strength" />
            </div>
            <fieldset>
              <legend className={LBL}>Type</legend>
              <div className="flex flex-wrap gap-2">
                {KINDS.map((k) => (
                  <button key={k} type="button" aria-pressed={kind === k} onClick={() => setKind(k)} className={"h-11 rounded-full border px-4 text-sm font-semibold capitalize transition-colors " + (kind === k ? "border-primary bg-primary text-[#0B0C09]" : "border-white/[0.1] bg-white/[0.03] text-[#D3D6CB] hover:bg-white/[0.07]")}>{k}</button>
                ))}
              </div>
            </fieldset>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label htmlFor="lw-date" className={LBL}>Date</label>
                <input id="lw-date" type="date" max={today} className={INPUT} value={day} onChange={(e) => setDay(e.target.value)} />
              </div>
              <div>
                <label htmlFor="lw-min" className={LBL}>Duration (min)</label>
                <input id="lw-min" type="number" min={0} inputMode="numeric" className={INPUT + " tnum"} value={minutes} onChange={(e) => setMinutes(e.target.value)} />
              </div>
            </div>
          </section>

          <section aria-labelledby="ex-h" className={CARD + " p-5 sm:p-6"}>
            <div className="flex items-baseline justify-between gap-3">
              <h2 id="ex-h" className="text-lg font-bold">{cardio ? "Distance" : "Exercises"}</h2>
              <span className="tnum text-sm text-[#B4B8A9]">{volume ? volume.toLocaleString("en-US") + " kg lifted" : ""}{volume && distance ? " · " : ""}{distance ? Math.round(distance * 10) / 10 + " km" : ""}</span>
            </div>
            <ul className="mt-4 space-y-3">
              <AnimatePresence initial={false}>
                {exs.map((e, i) => (
                  <motion.li key={e.id} layout initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} transition={{ duration: 0.25, ease: EASE }} className="overflow-hidden">
                    <div className="rounded-xl border border-white/[0.07] bg-white/[0.03] p-3">
                      <div className="flex items-center gap-2">
                        <label htmlFor={"ex-n-" + e.id} className="sr-only">Exercise {i + 1} name</label>
                        <input id={"ex-n-" + e.id} className={INPUT + " h-11 flex-1"} value={e.name} onChange={(ev) => patchEx(e.id, { name: ev.target.value })} placeholder="Exercise name" />
                        <button type="button" aria-label={"Remove " + (e.name || "exercise")} onClick={() => setExs((x) => x.filter((y) => y.id !== e.id))} className="grid h-11 w-11 shrink-0 place-items-center rounded-xl text-[#B4B8A9] transition-colors hover:bg-white/[0.08] hover:text-[#F2F3EC]"><X size={18} aria-hidden /></button>
                      </div>
                      {cardio ? (
                        <div className="mt-2 grid grid-cols-2 gap-2">
                          <label className="text-[13px] font-medium text-[#B4B8A9]">Distance (km)<input type="number" min={0} step="0.1" inputMode="decimal" className={INPUT + " tnum mt-1 h-11"} value={e.km} onChange={(ev) => patchEx(e.id, { km: ev.target.value })} /></label>
                          <label className="text-[13px] font-medium text-[#B4B8A9]">Time (min)<input type="number" min={0} inputMode="numeric" className={INPUT + " tnum mt-1 h-11"} value={e.min} onChange={(ev) => patchEx(e.id, { min: ev.target.value })} /></label>
                        </div>
                      ) : (
                        <div className="mt-2 grid grid-cols-3 gap-2">
                          <label className="text-[13px] font-medium text-[#B4B8A9]">Sets<input type="number" min={0} inputMode="numeric" className={INPUT + " tnum mt-1 h-11"} value={e.sets} onChange={(ev) => patchEx(e.id, { sets: ev.target.value })} /></label>
                          <label className="text-[13px] font-medium text-[#B4B8A9]">Reps<input type="number" min={0} inputMode="numeric" className={INPUT + " tnum mt-1 h-11"} value={e.reps} onChange={(ev) => patchEx(e.id, { reps: ev.target.value })} /></label>
                          <label className="text-[13px] font-medium text-[#B4B8A9]">Weight (kg)<input type="number" min={0} step="0.5" inputMode="decimal" className={INPUT + " tnum mt-1 h-11"} value={e.weight} onChange={(ev) => patchEx(e.id, { weight: ev.target.value })} /></label>
                        </div>
                      )}
                    </div>
                  </motion.li>
                ))}
              </AnimatePresence>
            </ul>
            {exs.length === 0 ? <p className="text-[15px] text-[#B4B8A9]">{cardio ? "Add the distance you covered. Runs over 3 km count toward your pace record." : "Add what you lifted. Weights feed your personal records and weekly volume."}</p> : null}
            <div className="mt-4 flex flex-wrap gap-2">
              {(cardio ? CARDIO : LIFTS).map((p) => (
                <button key={p} type="button" onClick={() => addEx(p)} className="flex h-10 items-center gap-1.5 rounded-full border border-white/[0.12] px-3.5 text-sm font-medium text-[#D3D6CB] transition-colors hover:bg-white/[0.06]"><Plus size={14} aria-hidden />{p}</button>
              ))}
              <button type="button" onClick={() => addEx("")} className="flex h-10 items-center gap-1.5 rounded-full bg-white/[0.08] px-3.5 text-sm font-semibold text-[#F2F3EC] transition-colors hover:bg-white/[0.12]"><Plus size={14} aria-hidden />Other</button>
            </div>
          </section>
        </div>

        <div className="space-y-4 lg:col-span-2 lg:space-y-5">
          <section aria-labelledby="eff-h" className={CARD + " p-5 sm:p-6"}>
            <div className="flex items-end justify-between">
              <h2 id="eff-h" className="text-lg font-bold">Effort</h2>
              <div className="text-right" aria-live="polite">
                <span className="tnum text-4xl font-extrabold tracking-tight text-primary">{effort}</span>
                <span className="text-base text-[#B4B8A9]">/10</span>
                <div className="text-sm font-semibold text-[#D3D6CB]">{EFFORT_WORD(effort)}</div>
              </div>
            </div>
            <div className="mt-4 grid grid-cols-5 gap-2" role="radiogroup" aria-label="Effort from 1 to 10">
              {Array.from({ length: 10 }, (_, i) => i + 1).map((n) => (
                <button key={n} type="button" role="radio" aria-checked={effort === n} aria-label={"Effort " + n + ", " + EFFORT_WORD(n)} onClick={() => setEffort(n)} className={"tnum h-11 rounded-xl border text-[15px] font-bold transition-colors " + (n === effort ? effortTone(n) : n < effort ? "border-primary/30 bg-primary/15 text-[#E8F8B0]" : "border-white/[0.08] bg-white/[0.03] text-[#B4B8A9] hover:bg-white/[0.07]")}>{n}</button>
              ))}
            </div>
            <p className="mt-3 text-[13px] text-[#9A9E8F]">How hard it felt overall. 5 is a steady session; 9 and up should be rare.</p>
          </section>
          <section className={CARD + " p-5 sm:p-6"}>
            <label htmlFor="lw-notes" className={LBL}>Notes for your coach <span className="font-normal text-[#9A9E8F]">(optional)</span></label>
            <textarea id="lw-notes" rows={4} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="How did it feel? Anything hurt?" className="w-full rounded-xl border border-white/[0.1] bg-white/[0.04] p-4 text-[15px] text-[#F2F3EC] outline-none transition-colors focus:border-primary" />
          </section>
          {err ? <p role="alert" className="rounded-xl border border-[#FF6B6B]/30 bg-[#FF6B6B]/10 px-4 py-3 text-sm text-[#FFB3B3]">{err}</p> : null}
          <button type="submit" disabled={busy || !app} className="flex h-14 w-full items-center justify-center gap-2 rounded-xl bg-primary text-base font-bold text-[#0B0C09] transition-transform active:scale-[0.99] disabled:opacity-60">
            <Check size={20} strokeWidth={2.75} aria-hidden />{busy ? "Saving…" : "Finish workout"}
          </button>
        </div>
      </form>
      <AnimatePresence>{done ? <Celebrate {...done} onDone={reset} onHome={() => app?.navigate("/")} /> : null}</AnimatePresence>
    </Shell>
  );
}

import React, { useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, Plus, HeartPulse, BarChart3, LogOut, Zap, ChevronDown, MessageSquare, Dumbbell, Calendar, FileText, Clock } from "lucide-react";

const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2,.sx h3,.sx h4{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx .tnum{font-variant-numeric:tabular-nums}
.sx .disp{font-weight:800;letter-spacing:-0.03em;text-transform:uppercase;line-height:.95}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const CARD = "rounded-2xl border border-white/[0.07] bg-[#14160F]";
const NAV = [
  { to: "/", label: "Today", I: Home },
  { to: "/log", label: "Log", I: Plus },
  { to: "/checkin", label: "Check-in", I: HeartPulse },
  { to: "/activity", label: "Activity", I: BarChart3 },
];
const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const dow = (s: string): number => (new Date(s + "T00:00:00Z").getUTCDay() + 6) % 7;
const fmt = (s: string, o: Intl.DateTimeFormatOptions): string => (s ? new Date(s + "T00:00:00Z").toLocaleDateString("en-US", { ...o, timeZone: "UTC" }) : "");
const dur = (m: number): string => (m >= 60 ? Math.floor(m / 60) + "h " + String(m % 60).padStart(2, "0") + "m" : m + " min");
type Ex = { n?: string; s?: number; r?: number; w?: number; km?: number; min?: number };
function parseEx(v: unknown): Ex[] {
  try {
    const j = JSON.parse(String(v ?? "[]"));
    return Array.isArray(j) ? (j as Ex[]) : [];
  } catch (e) {
    return [];
  }
}

