export default function Activity({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [tab, setTab] = useState<"workouts" | "plan" | "digests">("workouts");
  const [open, setOpen] = useState<string | null>(null);
  const [limit, setLimit] = useState(15);
  const me = app?.me("athlete");
  const loading = app ? app.loading("workout") : false;
  const rawW = app ? app.rows("workout") : [];
  const workouts = useMemo(() => rawW.filter((w) => !me || String(w.athlete_id) === me).sort((a, b) => ds(b.day).localeCompare(ds(a.day))), [rawW, me]);
  const feedback = app ? app.rows("feedback") : [];
  const plans = (app ? app.rows("plan_day") : []).filter((p) => ds(p.day) >= addDays(today, -dow(today))).sort((a, b) => ds(a.day).localeCompare(ds(b.day)));
  const digests = (app ? app.rows("digest") : []).slice().sort((a, b) => ds(b.week_start).localeCompare(ds(a.week_start)));

  const start = addDays(today, -dow(today) - 7 * 11);
  const cells = useMemo(() => {
    const byDay = new Map<string, number>();
    workouts.forEach((w) => byDay.set(ds(w.day), (byDay.get(ds(w.day)) || 0) + num(w.duration_min)));
    return Array.from({ length: 12 * 7 }, (_, i) => {
      const d = addDays(start, i);
      return { d, v: byDay.get(d) || 0, future: d > today };
    });
  }, [workouts, today, start]);
  const activeDays = cells.filter((c) => c.v > 0).length;
  const months = Array.from({ length: 12 }, (_, w) => {
    const d = addDays(start, w * 7);
    const prev = w ? addDays(start, (w - 1) * 7) : "";
    return w === 0 || d.slice(5, 7) !== prev.slice(5, 7) ? fmt(d, { month: "short" }) : "";
  });
  const summary = useMemo(() => {
    const past = cells.filter((c) => !c.future);
    const mins = past.reduce((s, c) => s + c.v, 0);
    let run = 0;
    let longest = 0;
    past.forEach((c) => {
      run = c.v > 0 ? run + 1 : 0;
      if (run > longest) longest = run;
    });
    const n = workouts.filter((w) => ds(w.day) >= start).length;
    return [
      { l: "Weekly avg", v: String(Math.round((n / 12) * 10) / 10), u: "" },
      { l: "Hours", v: String(Math.round(mins / 60)), u: "" },
      { l: "Best streak", v: String(longest), u: longest === 1 ? "day" : "days" },
    ];
  }, [cells, workouts, start]);
  const shade = (v: number) => (v === 0 ? "bg-white/[0.06]" : v < 40 ? "bg-primary/35" : v < 70 ? "bg-primary/65" : "bg-primary");

  const tabs: [typeof tab, string, number][] = [["workouts", "Workouts", workouts.length], ["plan", "This week", plans.length], ["digests", "Digests", digests.length]];
  return (
