        </div>
        <div className="mt-4 flex items-center justify-end gap-1.5 text-xs text-[#9A9E8F]" aria-hidden>
          <span className="mr-1">Less</span>
          {["bg-white/[0.06]", "bg-primary/35", "bg-primary/65", "bg-primary"].map((c) => <span key={c} className={"h-3.5 w-3.5 rounded-[4px] " + c} />)}
          <span className="ml-1">More</span>
