export default function CoachRoster({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const [fbFor, setFbFor] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [tone, setTone] = useState<"praise" | "adjust" | "question">("praise");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [sent, setSent] = useState<string[]>([]);
  const [justSent, setJustSent] = useState("");

  const me = app?.me("coach");
  const loading = app ? app.loading("athlete") : false;
  const athletes = app ? app.rows("athlete") : [];
  const workouts = app ? app.rows("workout") : [];
  const checkins = app ? app.rows("checkin") : [];
  const feedback = app ? app.rows("feedback") : [];
  const coaches = app ? app.rows("coach") : [];
  const mine = coaches.find((c) => String(c.id) === me);
  const noProfile = !!app && !me && !app.loading("coach") && coaches.length > 0;
  const weekStart = addDays(today, -6);

  const roster = useMemo(() => {
    return athletes
      .map((a) => {
        const id = String(a.id);
        const ws = workouts.filter((w) => String(w.athlete_id) === id);
        const days = new Set(ws.map((w) => ds(w.day)));
        const cks = checkins.filter((c) => String(c.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day)));
        const week = ws.filter((w) => ds(w.day) >= weekStart).length;
        const last = [...ws].sort((x, y) => ds(y.day).localeCompare(ds(x.day)))[0];
        const ck = cks[0];
        const reasons: string[] = [];
        if (ck && ds(ck.day) >= addDays(today, -2)) {
          if (num(ck.soreness) >= 4) reasons.push("Soreness " + num(ck.soreness) + "/5 " + ago(ds(ck.day), today));
          if (num(ck.sleep_hours) < 6) reasons.push("Slept " + num(ck.sleep_hours) + " h " + ago(ds(ck.day), today));
        }
        if (!last || ds(last.day) < addDays(today, -3)) reasons.push(last ? "No session since " + fmt(ds(last.day), { weekday: "long" }) : "No sessions logged");
        return { a, id, streak: calcStreak(days, today), last, ck, week, target: num(a.weekly_target) || 4, reasons };
      })
      .sort((x, y) => y.reasons.length - x.reasons.length || y.streak - x.streak);
  }, [athletes, workouts, checkins, today, weekStart]);

  const flagged = roster.filter((r) => r.reasons.length > 0);
  const onTarget = roster.filter((r) => r.week >= r.target).length;
  const queueAll = useMemo(
    () => workouts.filter((w) => ds(w.day) >= weekStart && !feedback.some((f) => String(f.workout_id) === String(w.id)) && !sent.includes(String(w.id))).sort((a, b) => ds(b.day).localeCompare(ds(a.day)) || String(b.created_at ?? "").localeCompare(String(a.created_at ?? ""))),
    [workouts, feedback, sent, weekStart]
  );
  const [showAll, setShowAll] = useState(false);
  const queue = showAll ? queueAll : queueAll.slice(0, 6);

  async function send(w: Row) {
    if (!app || !msg.trim()) return;
    setBusy(true);
    setErr("");
    try {
