      </main>
    </div>
  );
}

import React, { useMemo, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { LogOut, Zap, Flame, ArrowLeft, Send, Check, Calendar, MessageSquare, Sparkles, Target, AlertTriangle } from "lucide-react";

type Row = Record<string, unknown>;
const EASE = [0.22, 1, 0.36, 1] as const;
const CSS = `
:root{color-scheme:dark}
html,body{background:#0B0C09}
body{text-shadow:none!important;transition-timing-function:cubic-bezier(.22,1,.36,1)!important}
.sx{font-family:Inter,'Inter Variable',ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased}
.sx h1,.sx h2,.sx h3,.sx h4{font-family:inherit;text-shadow:none}
.sx ::selection{background:#C6F432;color:#0B0C09}
.sx :focus-visible{outline:2px solid #C6F432;outline-offset:2px}
.sx .tnum{font-variant-numeric:tabular-nums}
.sx .disp{font-weight:800;letter-spacing:-0.03em;text-transform:uppercase;line-height:.95}
.sx textarea::placeholder,.sx input::placeholder{color:#8F9384}
@media (prefers-reduced-motion: reduce){.sx *{animation:none!important;transition:none!important}}
`;
const CARD = "rounded-2xl border border-white/[0.07] bg-[#14160F]";
const INPUT = "h-11 w-full rounded-xl border border-white/[0.1] bg-white/[0.04] px-3 text-[15px] text-[#F2F3EC] outline-none transition-colors [color-scheme:dark] focus:border-primary";
const ds = (v: unknown): string => String(v ?? "").slice(0, 10);
const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const addDays = (s: string, n: number): string => {
  const d = new Date(s + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const dow = (s: string): number => (new Date(s + "T00:00:00Z").getUTCDay() + 6) % 7;
const fmt = (s: string, o: Intl.DateTimeFormatOptions): string => (s ? new Date(s + "T00:00:00Z").toLocaleDateString("en-US", { ...o, timeZone: "UTC" }) : "");
const MOOD_L = ["Rough", "Low", "Okay", "Good", "Great"];
const KINDS = ["strength", "run", "conditioning", "mobility", "ride", "rest"];
const TEMPLATE = [
  { title: "Lower Body Strength", kind: "strength", details: "Squat 5x5 · RDL 3x8 · Lunges 3x10", min: "60" },
  { title: "Easy Run", kind: "run", details: "6 km easy pace", min: "40" },
  { title: "Upper Body Strength", kind: "strength", details: "Bench 5x5 · Rows 4x8 · OHP 3x8", min: "60" },
  { title: "Mobility Flow", kind: "mobility", details: "Hips, thoracic, ankles", min: "30" },
  { title: "Tempo Intervals", kind: "run", details: "4 x 1 km at tempo", min: "45" },
  { title: "Long Session", kind: "conditioning", details: "Steady aerobic work", min: "75" },
  { title: "Rest Day", kind: "rest", details: "Walk, sleep, eat well", min: "0" },
];
function calcStreak(days: Set<string>, today: string): number {
  let cur = days.has(today) ? today : addDays(today, -1);
  let n = 0;
  while (days.has(cur)) {
    n++;
    cur = addDays(cur, -1);
  }
  return n;
}
function ago(d: string, today: string): string {
  const n = Math.round((new Date(today + "T00:00:00Z").getTime() - new Date(d + "T00:00:00Z").getTime()) / 86400000);
  return n <= 0 ? "Today" : n === 1 ? "Yesterday" : fmt(d, { weekday: "short", month: "short", day: "numeric" });
}

function ToneBtns({ tone, setTone }: { tone: string; setTone: (t: "praise" | "adjust" | "question") => void }) {
  return (
    <div role="radiogroup" aria-label="Tone" className="flex gap-2">
      {(["praise", "adjust", "question"] as const).map((t) => (
        <button key={t} type="button" role="radio" aria-checked={tone === t} onClick={() => setTone(t)} className={"h-10 flex-1 rounded-lg text-sm font-semibold capitalize transition-colors sm:flex-none sm:px-4 " + (tone === t ? "bg-primary text-[#0B0C09]" : "bg-white/[0.06] text-[#D3D6CB] hover:bg-white/[0.1]")}>{t}</button>
      ))}
    </div>
  );
}

export default function CoachAthlete({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [today] = useState(() => new Date().toISOString().slice(0, 10));
  const id = app?.params.id || "";
  const me = app?.me("coach");
  const loading = app ? app.loading("athlete") : false;
  const athletes = app ? app.rows("athlete") : [];
  const a = athletes.find((x) => String(x.id) === id);
  const coaches = app ? app.rows("coach") : [];
  const mine = coaches.find((c) => String(c.id) === me);
  const rawW = app ? app.rows("workout") : [];
  const workouts = useMemo(() => rawW.filter((w) => String(w.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day))), [rawW, id]);
  const checkins = (app ? app.rows("checkin") : []).filter((c) => String(c.athlete_id) === id).sort((x, y) => ds(y.day).localeCompare(ds(x.day)));
  const feedback = (app ? app.rows("feedback") : []).filter((f) => String(f.athlete_id) === id);
  const plans = (app ? app.rows("plan_day") : []).filter((p) => String(p.athlete_id) === id);
  const allPlans = app ? app.rows("plan_day") : [];

  const [tab, setTab] = useState<"logs" | "plan" | "checkins">("logs");
  const [fbFor, setFbFor] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [tone, setTone] = useState<"praise" | "adjust" | "question">("praise");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const nextMon = addDays(today, 7 - dow(today));
  const [weekStart, setWeekStart] = useState(nextMon);
  const [draft, setDraft] = useState(TEMPLATE);
  const [planBusy, setPlanBusy] = useState(false);
  const [planMsg, setPlanMsg] = useState("");
  const [planErr, setPlanErr] = useState("");
  const [limit, setLimit] = useState(10);

  const days = useMemo(() => new Set(workouts.map((w) => ds(w.day))), [workouts]);
  const streak = calcStreak(days, today);
  const wk = workouts.filter((w) => ds(w.day) >= addDays(today, -6));
  const mins = wk.reduce((s, w) => s + num(w.duration_min), 0);
  const vol = wk.reduce((s, w) => s + num(w.volume), 0);
  const eff = wk.length ? wk.reduce((s, w) => s + num(w.effort), 0) / wk.length : 0;
  const target = num(a?.weekly_target) || 4;
  const series = Array.from({ length: 14 }, (_, i) => {
    const d = addDays(today, i - 13);
    return { d, v: workouts.filter((w) => ds(w.day) === d).reduce((s, w) => s + num(w.duration_min), 0) };
  });
  const maxV = Math.max(1, ...series.map((s) => s.v));
  const weekPlans = plans.filter((p) => ds(p.day) >= weekStart && ds(p.day) <= addDays(weekStart, 6)).sort((x, y) => ds(x.day).localeCompare(ds(y.day)));
  const lastCk = checkins[0];
  const ckFlag = lastCk && ds(lastCk.day) >= addDays(today, -2) && (num(lastCk.soreness) >= 4 || num(lastCk.sleep_hours) < 6);
  const firstName = a ? String(a.name).split(" ")[0] : "the athlete";

  async function sendFb(w: Row) {
    if (!app || !msg.trim()) return;
    setBusy(true);
    setErr("");
    try {
      await app.create("feedback", { workout_id: String(w.id), athlete_id: id, coach_id: me ?? null, coach_name: mine ? String(mine.name) : app.user.name, workout_title: String(w.title), message: msg.trim(), tone });
      setFbFor(null);
      setMsg("");
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't send that feedback. Try again in a moment.");
    }
    setBusy(false);
  }

  const [aiBusy, setAiBusy] = useState(false);
  const [aiNote, setAiNote] = useState("");
  const [aiFallback, setAiFallback] = useState(false);
  const [aiSent, setAiSent] = useState(false);
  const [aiErr, setAiErr] = useState("");
  const latest = workouts[0];

  async function draftNote() {
    if (!app || !a) return;
    setAiBusy(true);
    setAiFallback(false);
    setAiSent(false);
    setAiErr("");
    const wl = workouts.slice(0, 7).map((w) => ds(w.day) + ": " + String(w.title) + " (" + String(w.kind) + "), effort " + num(w.effort) + "/10, " + num(w.duration_min) + " min" + (w.notes ? ", note: " + String(w.notes).slice(0, 80) : ""));
    const cl = checkins.slice(0, 7).map((c) => ds(c.day) + ": sleep " + num(c.sleep_hours) + " h, mood " + num(c.mood) + "/5, soreness " + num(c.soreness) + "/5" + (c.note ? ", " + String(c.note).slice(0, 80) : ""));
    try {
      const timeout = new Promise<string>((_, rej) => setTimeout(() => rej(new Error("timeout")), 20000));
      const r = await Promise.race([timeout, app.ai.ask("Athlete: " + String(a.name) + ". Goal: " + String(a.goal ?? "get fitter") + ".\nLast workouts:\n" + (wl.join("\n") || "none") + "\nCheck-ins:\n" + (cl.join("\n") || "none") + "\nWrite the feedback note.", { system: "You are a warm, encouraging strength and endurance coach writing a short note to your athlete. 3 to 4 sentences, first person, address them by first name, cite one concrete detail from the logs, end with one clear next step. No lists, no emoji, no markdown.", maxTokens: 220 })]);
      const t = r.trim();
      if (!t) throw new Error("empty");
      setAiNote(t);
    } catch (e) {
      setAiFallback(true);
      setAiNote("");
    }
    setAiBusy(false);
  }

  async function sendAiNote() {
    if (!app || !latest || !aiNote.trim()) return;
    setAiBusy(true);
    setAiErr("");
    try {
      await app.create("feedback", { workout_id: String(latest.id), athlete_id: id, coach_id: me ?? null, coach_name: mine ? String(mine.name) : app.user.name, workout_title: String(latest.title), message: aiNote.trim(), tone: "praise" });
      setAiSent(true);
      setAiNote("");
    } catch (e) {
      setAiErr(e instanceof Error ? e.message : "Couldn't send the note. Try again in a moment.");
    }
    setAiBusy(false);
  }

  async function assign(ev: React.FormEvent) {
    ev.preventDefault();
    if (!app) return;
    setPlanBusy(true);
    setPlanMsg("");
    setPlanErr("");
    let n = 0;
    try {
      for (let i = 0; i < draft.length; i++) {
        const r = draft[i];
        if (!r.title.trim()) continue;
        const img = allPlans.find((p) => String(p.kind) === r.kind && p.image)?.image;
        await app.create("plan_day", { athlete_id: id, coach_id: me ?? null, day: addDays(weekStart, i), title: r.title.trim(), kind: r.kind, details: r.details, duration_min: num(r.min), ...(img ? { image: String(img) } : {}) });
        n++;
      }
      setPlanMsg("Assigned " + n + " days to " + firstName + " for the week of " + fmt(weekStart, { month: "short", day: "numeric" }) + ".");
    } catch (e) {
      setPlanErr((n ? n + " days saved, then: " : "") + (e instanceof Error ? e.message : "Couldn't assign the plan."));
    }
    setPlanBusy(false);
  }

  const tabs: [typeof tab, string][] = [["logs", "Training log"], ["plan", "Weekly plan"], ["checkins", "Check-ins"]];
  const enter = (i: number) => ({ initial: reduce ? false : { opacity: 0, y: 8 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.35, delay: reduce ? 0 : i * 0.04, ease: EASE } });

  return (
    <div className="sx min-h-[100dvh] bg-[#0B0C09] text-[#F2F3EC]">
      <style>{CSS}</style>
      <header className="sticky top-0 z-30 border-b border-white/[0.07] bg-[#0B0C09]">
        <div className="mx-auto flex h-16 max-w-7xl items-center gap-3 pl-2 pr-2 sm:px-6 lg:px-10">
          <button type="button" onClick={() => app?.navigate("/coach")} className="flex h-11 items-center gap-2 rounded-xl px-3 text-[15px] font-semibold text-[#D3D6CB] transition-colors hover:bg-white/[0.06] hover:text-[#F2F3EC]"><ArrowLeft size={18} aria-hidden /> Roster</button>
          <div className="mx-auto flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-lg bg-primary text-[#0B0C09]"><Zap size={18} strokeWidth={2.5} aria-hidden /></span>
            <span className="hidden text-xl font-extrabold uppercase tracking-tight sm:inline">Stride</span>
          </div>
          <button type="button" aria-label="Sign out" onClick={() => app?.auth.signOut()} className="grid h-11 w-11 place-items-center rounded-xl text-[#B4B8A9] transition-colors hover:bg-white/[0.06] hover:text-[#F2F3EC]"><LogOut size={18} aria-hidden /></button>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 pb-16 pt-6 sm:px-6 lg:px-10 lg:pt-10">
        {!a ? (
          loading || !app ? (
            <div className="grid gap-6 lg:grid-cols-12"><div className={CARD + " h-72 animate-pulse lg:col-span-4"} /><div className={CARD + " h-96 animate-pulse lg:col-span-8"} /></div>
          ) : (
            <div className={CARD + " mx-auto flex max-w-md flex-col items-center px-6 py-12 text-center"}>
              <p className="text-lg font-bold">Athlete not found</p>
              <p className="mt-1 text-[15px] text-[#B4B8A9]">They may have moved to another coach, or the link is out of date.</p>
              <button type="button" onClick={() => app?.navigate("/coach")} className="mt-5 h-11 rounded-xl bg-primary px-5 text-[15px] font-bold text-[#0B0C09]">Back to roster</button>
            </div>
          )
        ) : (
          <div className="grid gap-6 lg:grid-cols-12 lg:gap-8">
            <motion.aside {...enter(0)} className="space-y-4 lg:col-span-4">
              <section className={CARD + " p-5 sm:p-6"}>
                <div className="flex items-center gap-4">
                  <span className="grid h-16 w-16 shrink-0 place-items-center overflow-hidden rounded-full bg-white/[0.08] text-xl font-bold">{a.photo ? <img alt="" src={String(a.photo)} className="h-full w-full object-cover" /> : String(a.name).split(" ").filter(Boolean).slice(0, 2).map((p) => p[0]).join("").toUpperCase()}</span>
                  <div className="min-w-0">
                    <h1 className="disp truncate text-3xl sm:text-4xl">{String(a.name)}</h1>
                    <p className="mt-1 text-sm text-[#B4B8A9]"><span className="capitalize">{String(a.level ?? "athlete")}</span> · {target} sessions a week</p>
                  </div>
                </div>
                <p className="mt-4 flex items-start gap-2 text-[15px] text-[#E1E3DA]"><Target size={17} className="mt-0.5 shrink-0 text-primary" aria-hidden />{String(a.goal ?? "No goal set yet")}</p>
                {ckFlag && lastCk ? <p className="mt-3 flex items-start gap-2 rounded-xl bg-[#FF9B5E]/10 px-3 py-2.5 text-sm text-[#FFB98C]"><AlertTriangle size={16} className="mt-0.5 shrink-0" aria-hidden />{ago(ds(lastCk.day), today)}: {num(lastCk.sleep_hours)} h sleep, soreness {num(lastCk.soreness)}/5{lastCk.note ? ". “" + String(lastCk.note) + "”" : ""}</p> : null}
              </section>
              <dl className={CARD + " grid grid-cols-2"}>
                {[{ l: "Streak", v: streak + (streak === 1 ? " day" : " days"), f: true }, { l: "Sessions, 7 days", v: wk.length + " of " + target }, { l: "Time, 7 days", v: mins >= 60 ? Math.floor(mins / 60) + "h " + String(mins % 60).padStart(2, "0") + "m" : mins + " min" }, { l: "Avg effort", v: eff ? eff.toFixed(1) + "/10" : "–" }].map((s, i) => (
                  <div key={s.l} className={"p-4 " + (i % 2 ? "border-l border-white/[0.07] " : "") + (i >= 2 ? "border-t border-white/[0.07]" : "")}>
                    <dt className="flex items-center gap-1 text-[13px] text-[#9A9E8F]">{s.f ? <Flame size={13} className="text-primary" aria-hidden /> : null}{s.l}</dt>
                    <dd className="tnum mt-1 text-2xl font-extrabold tracking-tight">{s.v}</dd>
                  </div>
                ))}
              </dl>
              <section className={CARD + " p-5"} aria-labelledby="m14-h">
                <div className="flex items-baseline justify-between">
                  <h2 id="m14-h" className="text-[15px] font-bold">Minutes, last 14 days</h2>
                  <span className="tnum text-[13px] text-[#9A9E8F]">{vol ? vol.toLocaleString("en-US") + " kg this week" : ""}</span>
                </div>
                <div className="mt-4 flex h-24 items-end gap-1" role="img" aria-label={"Training minutes for the last 14 days, " + series.filter((s) => s.v).length + " active days"}>
                  {series.map((s, i) => (
                    <motion.div key={s.d} title={fmt(s.d, { month: "short", day: "numeric" }) + ": " + s.v + " min"} initial={reduce ? false : { height: 0 }} animate={{ height: (s.v ? Math.max(6, (s.v / maxV) * 100) : 4) + "%" }} transition={{ duration: 0.45, delay: reduce ? 0 : i * 0.02, ease: EASE }} className={"flex-1 rounded-[4px] " + (s.v ? "bg-primary" : "bg-white/[0.07]")} />
                  ))}
                </div>
                <div className="mt-2 flex justify-between text-xs text-[#9A9E8F]"><span>{fmt(series[0].d, { month: "short", day: "numeric" })}</span><span>Today</span></div>
              </section>
            </motion.aside>

            <section className="min-w-0 lg:col-span-8">
              <div role="tablist" aria-label="Athlete" className="flex w-full rounded-xl bg-white/[0.05] p-1 sm:w-fit">
                {tabs.map(([k, l]) => (
                  <button key={k} role="tab" type="button" aria-selected={tab === k} onClick={() => setTab(k)} className="relative h-11 flex-1 rounded-lg px-3 text-sm font-semibold sm:flex-none sm:px-4">
                    {tab === k ? <motion.span layoutId="coach-tab" transition={{ duration: 0.25, ease: EASE }} className="absolute inset-0 rounded-lg bg-primary" /> : null}
                    <span className={"relative " + (tab === k ? "text-[#0B0C09]" : "text-[#B4B8A9]")}>{l}</span>
                  </button>
                ))}
              </div>

              <div className="mt-4 space-y-4" role="tabpanel">
                {tab === "logs" ? (
                  <>
                    <section aria-labelledby="ai-h" className="rounded-2xl border border-primary/25 bg-primary/[0.05] p-5">
                      <div className="flex flex-wrap items-start justify-between gap-3">
                        <div className="min-w-0 flex-1 basis-[260px]">
                          <h2 id="ai-h" className="flex items-center gap-2 text-[15px] font-bold"><Sparkles size={17} className="text-primary" aria-hidden /> Draft feedback with AI</h2>
                          <p className="mt-1 text-sm text-[#B4B8A9]">Reads {firstName}'s last 7 sessions and check-ins and writes a note in your voice. Edit before you send.</p>
                        </div>
                        <button type="button" onClick={() => void draftNote()} disabled={aiBusy || workouts.length === 0} className="flex h-11 items-center gap-2 rounded-xl bg-primary px-4 text-[15px] font-bold text-[#0B0C09] disabled:opacity-50">
                          <Sparkles size={16} aria-hidden className={aiBusy && !aiNote && !reduce ? "animate-pulse" : ""} />{aiBusy && !aiNote ? "Drafting…" : aiNote ? "Redraft" : "Draft a note"}
                        </button>
                      </div>
                      <div aria-live="polite">
                        {aiBusy && !aiNote ? (
                          <div className="mt-4 space-y-2"><div className="h-4 w-full animate-pulse rounded bg-white/[0.07]" /><div className="h-4 w-11/12 animate-pulse rounded bg-white/[0.07]" /><div className="h-4 w-3/5 animate-pulse rounded bg-white/[0.07]" /></div>
                        ) : null}
                        {aiFallback ? <p className="mt-4 rounded-xl bg-white/[0.05] px-4 py-3 text-sm text-[#D3D6CB]">The AI assistant is unavailable right now. Try again in a minute, or reply to a session below.</p> : null}
                        {aiNote ? (
                          <div className="mt-4">
                            <label htmlFor="ai-note" className="sr-only">Draft feedback note</label>
                            <textarea id="ai-note" rows={5} value={aiNote} onChange={(e) => setAiNote(e.target.value)} className="w-full rounded-xl border border-white/[0.12] bg-[#0B0C09] p-4 text-[15px] leading-relaxed text-[#F2F3EC] outline-none transition-colors focus:border-primary" />
                            <div className="mt-2 flex flex-wrap items-center justify-between gap-3">
                              <span className="text-[13px] text-[#9A9E8F]">Attaches to {latest ? String(latest.title) + " (" + ago(ds(latest.day), today) + ")" : "the latest session"}</span>
                              <button type="button" onClick={() => void sendAiNote()} disabled={aiBusy || !aiNote.trim() || !latest} className="flex h-11 items-center gap-2 rounded-xl bg-[#F2F3EC] px-4 text-[15px] font-bold text-[#0B0C09] disabled:opacity-50"><Send size={15} aria-hidden />Send to {firstName}</button>
                            </div>
                          </div>
                        ) : null}
                        {aiSent ? <p role="status" className="mt-3 flex items-center gap-2 text-sm font-medium text-primary"><Check size={16} aria-hidden />Sent. {firstName} gets a notification.</p> : null}
                        {aiErr ? <p role="alert" className="mt-3 text-sm text-[#FFB3B3]">{aiErr}</p> : null}
                      </div>
                    </section>

                    {workouts.length === 0 ? (
                      <div className={CARD + " px-6 py-12 text-center"}><p className="text-lg font-bold">No sessions logged yet</p><p className="mt-1 text-[15px] text-[#B4B8A9]">When {firstName} logs a workout it appears here for your feedback.</p></div>
                    ) : (
                      <ul className={CARD + " divide-y divide-white/[0.07] overflow-hidden"}>
                        {workouts.slice(0, limit).map((w) => {
                          const wid = String(w.id);
                          const fbs = feedback.filter((f) => String(f.workout_id) === wid);
                          const open = fbFor === wid;
                          const meta = [num(w.duration_min) + " min", num(w.volume) ? num(w.volume).toLocaleString("en-US") + " kg" : "", num(w.distance_km) ? num(w.distance_km) + " km" : "", "effort " + num(w.effort)].filter(Boolean).join(" · ");
                          return (
                            <li key={wid} className="p-4 sm:p-5">
                              <div className="flex items-start gap-3">
                                <div className="min-w-0 flex-1">
                                  <div className="text-[13px] text-[#9A9E8F]">{ago(ds(w.day), today)} · <span className="capitalize">{String(w.kind)}</span></div>
                                  <div className="truncate text-[15px] font-semibold">{String(w.title)}</div>
                                  <div className="tnum text-[13px] text-[#B4B8A9]">{meta}</div>
                                </div>
                                <button type="button" aria-expanded={open} onClick={() => { setFbFor(open ? null : wid); setErr(""); setMsg(""); }} className={"flex h-10 shrink-0 items-center gap-1.5 rounded-lg px-3 text-sm font-semibold transition-colors " + (fbs.length ? "text-[#B4B8A9] hover:bg-white/[0.06] hover:text-[#F2F3EC]" : "bg-primary text-[#0B0C09]")}>
                                  <MessageSquare size={14} aria-hidden />{fbs.length ? "Add note" : "Reply"}
                                </button>
                              </div>
                              {w.notes ? <p className="mt-2 text-[15px] text-[#D3D6CB]">“{String(w.notes)}”</p> : null}
                              {fbs.map((f) => (
                                <div key={String(f.id)} className="mt-3 rounded-xl bg-white/[0.05] px-4 py-3">
                                  <div className="text-[13px] text-[#9A9E8F]">You · <span className="capitalize">{String(f.tone)}</span></div>
                                  <p className="mt-0.5 text-[15px] leading-relaxed text-[#E9EBE3]">{String(f.message)}</p>
                                </div>
                              ))}
                              <AnimatePresence initial={false}>
                                {open ? (
                                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.25, ease: EASE }} className="overflow-hidden">
                                    <form onSubmit={(e) => { e.preventDefault(); void sendFb(w); }} className="space-y-3 pt-4">
                                      <ToneBtns tone={tone} setTone={setTone} />
                                      <label htmlFor={"fb-" + wid} className="sr-only">Feedback message</label>
                                      <textarea id={"fb-" + wid} rows={3} value={msg} onChange={(e) => setMsg(e.target.value)} placeholder={"What should " + firstName + " keep or change next time?"} className="w-full rounded-xl border border-white/[0.1] bg-white/[0.04] p-3 text-[15px] text-[#F2F3EC] outline-none transition-colors focus:border-primary" />
                                      {err ? <p role="alert" className="text-sm text-[#FFB3B3]">{err}</p> : null}
                                      <button type="submit" disabled={busy || !msg.trim()} className="flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-primary text-[15px] font-bold text-[#0B0C09] disabled:opacity-50 sm:w-auto sm:px-5"><Send size={16} aria-hidden />{busy ? "Sending…" : "Send feedback"}</button>
                                    </form>
                                  </motion.div>
                                ) : null}
                              </AnimatePresence>
                            </li>
                          );
                        })}
                      </ul>
                    )}
                    {workouts.length > limit ? <button type="button" onClick={() => setLimit((l) => l + 15)} className="h-12 w-full rounded-xl border border-white/[0.1] text-[15px] font-semibold text-[#D3D6CB] transition-colors hover:bg-white/[0.04]">Show older sessions ({workouts.length - limit} more)</button> : null}
                  </>
                ) : null}

                {tab === "plan" ? (
                  <form onSubmit={(e) => void assign(e)} className="space-y-4">
                    <div className={CARD + " flex flex-wrap items-end justify-between gap-3 p-4 sm:p-5"}>
                      <div>
                        <label htmlFor="wk-start" className="mb-1.5 flex items-center gap-1.5 text-sm font-semibold text-[#D3D6CB]"><Calendar size={14} aria-hidden /> Week starting (Monday)</label>
                        <input id="wk-start" type="date" className={INPUT + " w-auto"} value={weekStart} onChange={(e) => setWeekStart(e.target.value)} />
                      </div>
                      <p className="text-sm text-[#B4B8A9]">{weekPlans.length ? weekPlans.length + " days already planned that week" : "Nothing planned that week yet"}</p>
                    </div>
                    {weekPlans.length ? (
                      <div className={CARD + " p-4 sm:p-5"}>
                        <h3 className="text-[15px] font-bold">Already on the calendar</h3>
                        <ul className="mt-2 divide-y divide-white/[0.06]">
                          {weekPlans.map((p) => <li key={String(p.id)} className="flex justify-between gap-3 py-2.5 text-[15px]"><span className="text-[#B4B8A9]">{fmt(ds(p.day), { weekday: "short", month: "short", day: "numeric" })}</span><span className="truncate font-semibold">{String(p.title)}</span></li>)}
                        </ul>
                      </div>
                    ) : null}
                    <ol className={CARD + " divide-y divide-white/[0.07]"}>
                      {draft.map((r, i) => (
                        <li key={i} className="p-4 sm:p-5">
                          <div className="mb-2 text-sm font-semibold text-primary">{fmt(addDays(weekStart, i), { weekday: "long", month: "short", day: "numeric" })}</div>
                          <div className="grid gap-2 sm:grid-cols-12">
                            <label className="sm:col-span-5"><span className="sr-only">Session title</span><input className={INPUT} value={r.title} placeholder="Session title (leave empty to skip)" onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, title: e.target.value } : x)))} /></label>
                            <label className="sm:col-span-4"><span className="sr-only">Type</span><select className={INPUT + " capitalize"} value={r.kind} onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, kind: e.target.value } : x)))}>{KINDS.map((k) => <option key={k} value={k}>{k}</option>)}</select></label>
                            <label className="relative sm:col-span-3"><span className="sr-only">Minutes</span><input className={INPUT + " tnum pr-12"} type="number" min={0} value={r.min} onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, min: e.target.value } : x)))} /><span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-sm text-[#9A9E8F]">min</span></label>
                            <label className="sm:col-span-12"><span className="sr-only">Details</span><input className={INPUT} value={r.details} placeholder="Details: sets, reps, pace" onChange={(e) => setDraft((d) => d.map((x, k) => (k === i ? { ...x, details: e.target.value } : x)))} /></label>
                          </div>
                        </li>
                      ))}
                    </ol>
                    {planMsg ? <p role="status" className="flex items-center gap-2 rounded-xl bg-primary/10 px-4 py-3 text-sm font-medium text-primary"><Check size={16} aria-hidden />{planMsg}</p> : null}
                    {planErr ? <p role="alert" className="rounded-xl border border-[#FF6B6B]/30 bg-[#FF6B6B]/10 px-4 py-3 text-sm text-[#FFB3B3]">{planErr}</p> : null}
                    <button type="submit" disabled={planBusy} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary text-base font-bold text-[#0B0C09] disabled:opacity-60">{planBusy ? "Assigning…" : "Assign week to " + firstName}</button>
                  </form>
                ) : null}

                {tab === "checkins" ? (
                  checkins.length === 0 ? (
                    <div className={CARD + " px-6 py-12 text-center"}><p className="text-lg font-bold">No check-ins yet</p><p className="mt-1 text-[15px] text-[#B4B8A9]">{firstName}'s daily sleep, mood and soreness will show here.</p></div>
                  ) : (
                    <div className={CARD + " overflow-x-auto"}>
                      <table className="w-full min-w-[520px] text-left text-[15px]">
                        <thead>
                          <tr className="border-b border-white/[0.07] text-[13px] text-[#9A9E8F]">
                            <th className="px-5 py-3 font-medium">Day</th>
                            <th className="px-3 py-3 text-right font-medium">Sleep</th>
                            <th className="px-3 py-3 font-medium">Mood</th>
                            <th className="px-3 py-3 text-right font-medium">Soreness</th>
                            <th className="px-5 py-3 font-medium">Note</th>
                          </tr>
                        </thead>
                        <tbody className="tnum divide-y divide-white/[0.06]">
                          {checkins.slice(0, 21).map((c) => {
                            const lowSleep = num(c.sleep_hours) < 6;
                            const sore = num(c.soreness) >= 4;
                            return (
                              <tr key={String(c.id)}>
                                <td className="whitespace-nowrap px-5 py-3 font-medium">{ago(ds(c.day), today)}</td>
                                <td className={"px-3 py-3 text-right " + (lowSleep ? "font-semibold text-[#FF9B5E]" : "")}>{num(c.sleep_hours)} h</td>
                                <td className="px-3 py-3 text-[#D3D6CB]">{MOOD_L[Math.max(0, Math.min(4, num(c.mood) - 1))]}</td>
                                <td className={"px-3 py-3 text-right " + (sore ? "font-semibold text-[#FF9B5E]" : "")}>{num(c.soreness)}/5</td>
                                <td className="px-5 py-3 text-[#B4B8A9]">{c.note ? String(c.note) : ""}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  )
                ) : null}
              </div>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

